window.kbPageData["views/entry/k-887d09ee4855eb15"] = {"key":"entry/k-887d09ee4855eb15","state":{"route":"entry/k-887d09ee4855eb15"},"node":{"id":"k-887d09ee4855eb15","mode":"k","title":"主要目标指标","type":"事实与事件","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["事实与事件"],"出处性质":["报告摘登"],"学科":["政治理论"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"（一）主要目标指标\n贯彻落实党中央《建议》明确的主要目标，《纲要（草案）》细化提出 20 项主要指标。\n经济发展方面，围绕增长、结构、效率提出 3 项指标。其中，综合考虑国内外形势和各方面\n因素，兼顾需要与可能，提出国内生产总值增长保持在合理区间、各年度视情提出，为到\n2035 年人均国内生产总值比…","sources":[{"id":"1f607c14071800c9","label":"主要目标指标","topic":"年度政府工作","category":"时政","text":"（一）主要目标指标\n贯彻落实党中央《建议》明确的主要目标，《纲要（草案）》细化提出 20 项主要指标。\n经济发展方面，围绕增长、结构、效率提出 3 项指标。其中，综合考虑国内外形势和各方面\n因素，兼顾需要与可能，提出国内生产总值增长保持在合理区间、各年度视情提出，为到\n2035 年人均国内生产总值比 2020 年翻一番、达到中等发达国家水平打好基础。创新驱动方\n面，围绕创新投入及其成效提出 3 项指标。其中，充分考虑研发投入增长趋势和企业投入能\n力，提出全社会研发经费投入①年均增长 7%以上，与“十四五”规划目标保持一致，确保研\n发投入力度不减。民生福祉方面，为更好解决人民群众急难愁盼问题，针对性提出就业、收\n入、教育、医疗、健康、“一老一小”等 7 项指标。绿色低碳方面，围绕降碳减污、生态环\n保等提出 5 项指标。其中，根据国家自主贡献目标②，提出单位国内生产总值二氧化碳排放\n累计降低 17%，继续推动重点领域绿色低碳转型。安全保障方面，围绕粮食、能源生产能力\n提出 2 项指标，着力夯实国家安全重要基础保障。","source":{"doc":"6cbfb01fe723bba64b75","first":15,"last":15,"page":15,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-887d09ee4855eb15":[]}};
